#!/bin/sh
# generated by cluster/overnight.py
cd "$HOME/universe-1" || exit 1
mkdir -p results/life
S=results/life/overnight_status.txt
echo "$(date -u +%FT%TZ) overnight.sh started on $(hostname)" >> $S
(
  while pgrep -f "^python3 cluster/exp06b_node.py" >/dev/null 2>&1; do sleep 60; done
  mkdir -p results/life/shrmul_s1
  echo "$(date -u +%FT%TZ) start shrmul_s1 slot 0" >> $S
  nice -n 10 life/u1life_vk --gpu 0 --isa SWAP,ADD,NAND,XOR,SHR,MUL,SKZ,HALT --N 1024 --seed 1 --ticks 200000 --report-every 1000 --income 8 --ppm-every 100 --out-dir results/life/shrmul_s1 --dump-final > results/life/shrmul_s1/run.log 2>&1
  echo "$(date -u +%FT%TZ) end shrmul_s1 exit $?" >> $S
  mkdir -p results/life/swap_2048_s1
  echo "$(date -u +%FT%TZ) start swap_2048_s1 slot 0" >> $S
  nice -n 10 life/u1life_vk --gpu 0 --isa SWAP,LDI,NAND,ADD,ROL,SKNZ,INC,HALT --N 2048 --seed 1 --ticks 3000000 --report-every 1000 --income 8 --ppm-every 4000 --out-dir results/life/swap_2048_s1 --dump-final > results/life/swap_2048_s1/run.log 2>&1
  echo "$(date -u +%FT%TZ) end swap_2048_s1 exit $?" >> $S
) &
(
  while pgrep -f "^python3 cluster/exp06b_node.py" >/dev/null 2>&1; do sleep 60; done
  mkdir -p results/life/shrmul_s2
  echo "$(date -u +%FT%TZ) start shrmul_s2 slot 1" >> $S
  nice -n 10 life/u1life_vk --gpu 1 --isa SWAP,ADD,NAND,XOR,SHR,MUL,SKZ,HALT --N 1024 --seed 2 --ticks 200000 --report-every 1000 --income 8 --ppm-every 100 --out-dir results/life/shrmul_s2 --dump-final > results/life/shrmul_s2/run.log 2>&1
  echo "$(date -u +%FT%TZ) end shrmul_s2 exit $?" >> $S
  mkdir -p results/life/swap_long_rc64
  echo "$(date -u +%FT%TZ) start swap_long_rc64 slot 1" >> $S
  nice -n 10 life/u1life_vk --gpu 1 --isa SWAP,LDI,NAND,ADD,ROL,SKNZ,INC,HALT --N 1024 --seed 1 --ticks 6000000 --report-every 1000 --income 8 --repro-cost 64 --ppm-every 5000 --out-dir results/life/swap_long_rc64 --dump-final > results/life/swap_long_rc64/run.log 2>&1
  echo "$(date -u +%FT%TZ) end swap_long_rc64 exit $?" >> $S
  mkdir -p results/life/shrmul_long_s1
  echo "$(date -u +%FT%TZ) start shrmul_long_s1 slot 1" >> $S
  nice -n 10 life/u1life_vk --gpu 1 --isa SWAP,ADD,NAND,XOR,SHR,MUL,SKZ,HALT --N 1024 --seed 1 --ticks 6000000 --report-every 1000 --income 8 --ppm-every 4000 --out-dir results/life/shrmul_long_s1 --dump-final > results/life/shrmul_long_s1/run.log 2>&1
  echo "$(date -u +%FT%TZ) end shrmul_long_s1 exit $?" >> $S
) &
(
  mkdir -p results/life/cpu_swap_512_s1
  echo "$(date -u +%FT%TZ) start cpu_swap_512_s1 slot cpu" >> $S
  nice -n 19 life/u1life_cpu --isa SWAP,LDI,NAND,ADD,ROL,SKNZ,INC,HALT --N 512 --seed 1 --ticks 2500000 --report-every 1000 --income 8 --ppm-every 3000 --threads 8 --out-dir results/life/cpu_swap_512_s1 --dump-final > results/life/cpu_swap_512_s1/run.log 2>&1
  echo "$(date -u +%FT%TZ) end cpu_swap_512_s1 exit $?" >> $S
) &
wait
echo "$(date -u +%FT%TZ) overnight.sh finished" >> $S
